def is_valid(grid):
    for i in range(3):
        for j in range(3):
            block = [grid[i][j], grid[i][j+1], grid[i][j+2], grid[i+1][j], grid[i+1][j+1], grid[i+1][j+2], grid[i+2][j], grid[i+2][j+1], grid[i+2][j+2]]
            if len(set(block)) != 9:
                return False
    return True

def solve(grid):
    if len(grid) == 9:
        if is_valid(grid):
            return 1
        return 0

    count = 0
    for num in range(1, 10):
        if not grid[len(grid)-1][len(grid[0])-1]:
            grid[len(grid)-1][len(grid[0])-1] = num
            count += solve(grid)
            grid[len(grid)-1][len(grid[0])-1] = 0
    return count

def count_ways():
    grid = [[0]*9 for _ in range(3)]
    return solve(grid)

