import math

def greedy_algorithm(N):
    coins = [25, 10, 1]
    count = 0
    for coin in coins:
        while N >= coin:
            N -= coin
            count += 1
    return count

def is_greedy_successful(N):
    count = greedy_algorithm(N)
    return count == math.floor(N / 25) + math.floor(N / 10) + math.floor(N / 1)

def find_greedy_successful_N(limit):
    return [N for N in range(1, limit + 1) if is_greedy_successful(N)]

greedy_successful_N = find_greedy_successful_N(1000)
print(greedy_successful_N)

